query:
query billModal($sessionAbbreviation: String, $instrumentNbr: String, $instrumentType: InstrumentType) {
  instrument(where: { sessionAbbreviation: { eq: $sessionAbbreviation }, instrumentNbr: { eq: $instrumentNbr }, instrumentType: { eq: $instrumentType } }) {
    id instrumentNbr sessionName currentStatus shortTitle introducedFileUrl engrossedFileUrl enrolledFileUrl reenrolledFileUrl viewEnacted actNbr
  }
  histories: instrumentHistories(where: { sessionAbbreviation: { eq: $sessionAbbreviation }, instrumentNbr: { eq: $instrumentNbr } }) {
    data { instrumentNbr sessionName sessionYear calendarDate body matter amdSub committee voteType voteTitle rollCallNbr yeas nays }
  }
}
